import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  process.on('workerMessage', (value: any, src: any) => console.log('main workerMessage', JSON.stringify(value), src));
  const echo = new wt.Worker(`
    const wt = require('node:worker_threads');
    const keep = setInterval(() => {}, 1000);
    let hello = null, src0 = null;
    process.on('workerMessage', (value, src) => { hello = value.hello; src0 = src; });
    wt.parentPort.on('message', (m) => {
      if (m === 'report') wt.parentPort.postMessage('worker got ' + JSON.stringify({ hello }) + ' from ' + src0);
      else if (m === 'send') wt.postMessageToThread(0, { back: hello }).then((r) => { wt.parentPort.postMessage('worker send ' + r); }, (e) => { wt.parentPort.postMessage('worker send ' + e.code); });
    });
    wt.parentPort.postMessage('ready');
  `, { eval: true });
  let message: any = undefined;
  await new Promise<void>((resolve: () => void): void => { echo.once('message', (m: any) => { message = m; resolve(); }); });
  console.log('from echo:', message);
  const attempt1 = async (): Promise<void> => { try { await wt.postMessageToThread(echo.threadId, { hello: 'worker' }); console.log('A main send resolved', undefined); } catch (e: any) { console.log('A main send', e.name, e.code, JSON.stringify(e.message)); } };
  await attempt1();
  echo.postMessage('report');
  await new Promise<void>((resolve: () => void): void => { echo.once('message', (m: any) => { message = m; resolve(); }); });
  console.log('from echo:', message);
  echo.postMessage('send');
  await new Promise<void>((resolve: () => void): void => { echo.once('message', (m: any) => { message = m; resolve(); }); });
  console.log('from echo:', message);
  await echo.terminate();
  console.log('done');
}
